<?php $intro=tr('Suivez vos dossiers et retrouvez les décisions de la CNAM.','تابع ملفاتك واطّلع على قرارات الصندوق.'); require __DIR__ . '/../poste/page-heading.php'; ?>
<div class="poste-section">
    <?php if (isset($_SESSION['flash'])): ?><p class="alert alert-<?= e($_SESSION['flash']['type']==='danger'?'error':'success') ?>" role="status"><?= e($_SESSION['flash']['message']) ?></p><?php unset($_SESSION['flash']); endif; ?>
    <div class="poste-actions"><a class="button button-dark" href="index.php?page=remboursement-form"><?= e(tr('Nouvelle demande','طلب جديد')) ?></a></div>
    <?php if (!$liste): ?><section class="content-panel"><p><?= e(tr('Vous n’avez pas encore de demande de remboursement.','ليس لديك طلب استرجاع مصاريف بعد.')) ?></p></section>
    <?php else: ?><div class="table-scroll" role="region" aria-label="<?= e(tr('Mes remboursements','استرجاع مصاريفي')) ?>" tabindex="0"><table class="table poste-history-table"><thead><tr><th><?= e(tr('Référence','المرجع')) ?></th><th><?= e(tr('Bénéficiaire','المستفيد')) ?></th><th><?= e(tr('Soins','العلاج')) ?></th><th><?= e(tr('Montant demandé','المبلغ المطلوب')) ?></th><th><?= e(tr('Statut','الحالة')) ?></th><th><?= e(tr('Versement','الدفع')) ?></th><th><?= e(tr('Actions','الإجراءات')) ?></th></tr></thead><tbody>
    <?php foreach ($liste as $d): ?><tr><th scope="row"><bdi><?= e($d['reference']) ?></bdi></th><td><?= e($d['prenom'].' '.$d['nom']) ?></td><td><?= e($d['nature_soins']) ?><br><small><?= e(date('d/m/Y',strtotime($d['date_soins']))) ?></small></td><td><bdi><?= e(number_format((float)$d['montant_demande'],3,',',' ')) ?> TND</bdi><?php if ($d['montant_accorde']!==null): ?><br><small><?= e(tr('Accordé','المبلغ الموافق عليه')) ?> : <?= e(number_format((float)$d['montant_accorde'],3,',',' ')) ?> TND</small><?php endif; ?></td><td><span class="status-badge"><?= e(tr($d['statut'],$d['statut'])) ?></span><?php if (!empty($d['motif_decision'])): ?><p><?= e($d['motif_decision']) ?></p><?php endif; ?></td><td><?php if ($d['statut']==='PAYEE'): ?><bdi><?= e($d['reference_versement']) ?></bdi><br><?= e(date('d/m/Y',strtotime($d['date_versement']))) ?><?php else: ?>—<?php endif; ?></td><td><?php if (in_array($d['statut'],['BROUILLON','A_COMPLETER'],true)): ?><div class="poste-actions"><a class="button button-light" href="index.php?page=remboursement-form&amp;id=<?= e($d['id_demande']) ?>"><?= e(tr('Compléter','إكمال')) ?></a><?php if ($d['statut']==='BROUILLON'): ?><form method="post" action="index.php?page=remboursement-delete"><input type="hidden" name="csrf" value="<?= e($jeton) ?>"><input type="hidden" name="id_demande" value="<?= e($d['id_demande']) ?>"><input type="hidden" name="version" value="<?= e($d['version']) ?>"><button class="button button-light" type="submit"><?= e(tr('Supprimer','حذف')) ?></button></form><?php endif; ?></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</div>
